+
+        if (config.required && value === "") {
+          setError(input, config.requiredMessage);
+          return false;
+        }
+
+        if (value !== "" && config.pattern && !config.pattern.test(value)) {
+          setError(input, config.formatMessage);
+          return false;
+        }
+
+        clearError(input);
+        return true;
