+
+      function attachFormBehavior() {
+        const form = document.getElementById("support-form");
+        const status = document.getElementById("form-status");
+        const inputs = fields.map((field) => document.getElementById(field.id));
+
+        inputs.forEach((input) => {
+          input.addEventListener("input", () => {
+            validateInput(input);
+            status.textContent = "";
+          });
+        });
+
+        form.addEventListener("submit", (event) => {
+          event.preventDefault();
+          status.textContent = "";
+
+          const firstInvalid = inputs.find((input) => !validateInput(input));
+          if (firstInvalid) {
+            firstInvalid.focus();
+            return;
+          }
+
+          form.reset();
+          inputs.forEach(clearError);
+          status.textContent = "Thanks. Your support request is ready to send.";
+        });
+      }
+
+      document.getElementById("app").innerHTML = SupportContactForm();
+      attachFormBehavior();
+    </script>
+  </body>
+</html>
*** End Patch
